(7073792, 1075492, 97225, '<td valign="top">Nice diptych, beautifully processed. Meets the challenge well.</td>', 'Nice diptych, beautifully processed. Meets the challenge well.', '2013-07-19 03:39:55.000000', NULL, 1),
(7073793, 1076013, 97225, '<td valign="top">What a gorgeous pair of photos! They make a beautiful diptych which meets the challenge well.</td>', 'What a gorgeous pair of photos! They make a beautiful diptych which meets the challenge well.', '2013-07-19 03:41:29.000000', NULL, 1),
(7073794, 1076053, 97225, '<td valign="top">Great diptych. Perfect for this challenge.</td>', 'Great diptych. Perfect for this challenge.', '2013-07-19 03:42:28.000000', NULL, 1),
(7073796, 1076014, 97225, '<td valign="top">I love this! Beautiful photography and great challenge fit. The light is really lovely.</td>', 'I love this! Beautiful photography and great challenge fit. The light is really lovely.', '2013-07-19 03:44:05.000000', NULL, 1),
(7073836, 1076084, 12611, '<td valign="top">Masterful light and tones. I can taste that California Chard now.</td>', 'Masterful light and tones. I can taste that California Chard now.', '2013-07-19 06:28:51.000000', NULL, 1),
(7073837, 1076044, 12611, '<td valign="top">The blend of classic tones and modern steel works, and the isolation and subtie backgrounds you achieve is very well done.</td>', 'The blend of classic tones and modern steel works, and the isolation and subtie backgrounds you achieve is very well done.', '2013-07-19 06:30:20.000000', NULL, 1),
(7073838, 1075819, 12611, '<td valign="top">The composition, light and dark and glossy metallic shimmer make this a top shot in this challenge.</td>', 'The composition, light and dark and glossy metallic shimmer make this a top shot in this challenge.', '2013-07-19 06:31:16.000000', NULL, 1),
(7073839, 1075982, 12611, '<td valign="top">The back and forth, the feeling of inter-species...pathos?...simpatico? the points of view displayed perfectly. There is no criticism of this diptych that I could make. A top shot for sure.</td>', 'The back and forth, the feeling of inter-species...pathos?...simpatico? the points of view displayed perfectly. There is no criticism of this diptych that I could make. A top shot for sure.', '2013-07-19 06:33:01.000000', NULL, 1),
(7073840, 1076066, 12611, '<td valign="top">Funny, and great segments of pleasing green blur.</td>', 'Funny, and great segments of pleasing green blur.', '2013-07-19 06:33:51.000000', NULL, 1),
(7073841, 1076013, 12611, '<td valign="top">Very detailed, tight, and put together perfectly like a piece of Portmeirion.</td>', 'Very detailed, tight, and put together perfectly like a piece of Portmeirion.', '2013-07-19 06:35:41.000000', NULL, 1),
