(7075130, 1075819, 112828, '<td valign="top">The piano is your subject?<br/> <br/>Why wouldn''t it be looking at you?  In fact, why is it looking at all?</td>', 'The piano is your subject? Why wouldn''t it be looking at you?  In fact, why is it looking at all?', '2013-07-21 21:33:41.000000', NULL, 1),
(7075131, 1076079, 112828, '<td valign="top">Very nice.</td>', 'Very nice.', '2013-07-21 21:33:51.000000', NULL, 1),
(7075132, 1076052, 112828, '<td valign="top">Great work!  Very vibrant, if a little too dark.</td>', 'Great work!  Very vibrant, if a little too dark.', '2013-07-21 21:34:06.000000', NULL, 1),
